const https = require('https');

function fetchUrl(url) {
  return new Promise((resolve, reject) => {
    https.get(url, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve(data));
    }).on('error', reject);
  });
}

async function main() {
  const html = await fetchUrl('https://book.mcst.go.kr/html/main.php');
  const m = html.match(/name="search_type"[^>]*>([\s\S]*?)<\/select>/);
  if (m) {
    console.log('search_type options:', m[1]);
  }
}

main();

