const https = require('https');

function fetch(url) {
  return new Promise((resolve) => {
    https.get(url, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
      }
    }, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => resolve({ status: res.statusCode, headers: res.headers, data }));
    }).on('error', err => resolve({ error: err }));
  });
}

async function run() {
  const queries = ['비전조이', '0517476799', '051-747-6799', '이구창'];
  for (const q of queries) {
    const url = 'https://bizno.net/?query=' + encodeURIComponent(q);
    const r = await fetch(url);
    console.log(`\n=== Query: ${q} (Status: ${r.status}) ===`);
    if (r.data) {
      // Find matches in titles or company results
      const matches = [...r.data.matchAll(/<h4 class="titles">([\s\S]*?)<\/h4>/g)];
      console.log('Found titles:', matches.map(m => m[1].replace(/<[^>]+>/g, '').trim()));

      const tables = [...r.data.matchAll(/<table[\s\S]*?<\/table>/g)];
      for (const t of tables) {
        console.log('Table snippet:', t[0].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').substring(0, 300));
      }
    }
  }
}
run();
